  "city.doppel-parlor.description": "Un salón junto al Laboratorio Central de Investigación de Doppel. Se sienta a los invitados y se les entregan los diarios de investigación página a página.",
  "city.doppel-lab.description": "El instituto de investigación interno, en lo más profundo del laboratorio de Doppel. Aquí se reúnen los diarios que dejaron los investigadores enviados a Eternal.",
  "city.doppel-lab.displayName": "Doppel · Instituto de Investigación Interno",
  "city.doppel-office.description": "La oficina de administración de Doppel, que recopila los resultados de investigación y el uso de las reliquias. Las aprobaciones pasan por muchos niveles, así que la espera es larga.",
  "city.doppel-office.displayName": "Doppel · Oficina de Administración",
  "city.rust-garage.description": "El taller de mantenimiento de Rust. Las solicitudes para reparar equipos de investigación averiados no cesan.",
  "city.rust-garage.displayName": "Rust · Taller de Mantenimiento",
  "city.rust-lease.description": "La oficina de gestión de alquileres de Rust, que presta equipos de alto rendimiento. Hasta una sola prórroga arrastra largas negociaciones.",
  "city.rust-lease.displayName": "Rust · Oficina de Gestión de Alquileres",
  "city.doppel-upper.description": "La planta más alta del laboratorio de Doppel. Aquí se sientan quienes deciden el propósito de la investigación.",
  "city.doppel-upper.displayName": "Doppel · Alta Dirección",
  "city.rust-works.description": "Una inmensa fundición en el corazón de Rust. El diseño y la reparación de los equipos de investigación se reúnen en un solo lugar.",
  "city.rust-works.displayName": "Rust · Fundición Central",
  "city.odidi-embassy.description": "La sala de recepción donde Odidi, la ciudad que estudia los sueños, recibe a los visitantes externos. Las propuestas siempre las plantean ellos primero.",
  "city.odidi-embassy.displayName": "Odidi · Sala de Recepción Diplomática",
  "journal.interaction-doppel-lab-01.title": "Diario de la misión que no volvió",
  "journal.interaction-doppel-lab-01.body": "El diario de un investigador enviado a Eternal. La última página es una sola línea: «Ha llegado el relevo», y la casilla de la firma que hay debajo sigue vacía.",
  "city.department.exchange": "Oficina de canje",
  "city.department.council": "Consejo",
  "city.doppel-parlor.displayName": "Doppel · Salón del Laboratorio Central de Investigación",
  "shopClerk.obi.name": "Obi",
  "shopClerk.protia.name": "Protia",
  "shopClerk.haine.name": "Haine",
  "journal.interaction-doppel-01.title": "El cartel del Pasillo Azul",
  "journal.interaction-doppel-01.body": "El primer tablón del invernadero aún pide recibir a los cuerpos restaurados como nuevos vecinos, no como espectáculo.",
  "journal.interaction-doppel-02.title": "El saludo que se repite",
  "bond.torika.0": "¿Quién eres?",
  "bond.torika.1": "Has vuelto.",
  "bond.torika.2": "Puedes quedarte a mi lado.",
  "bond.torika.3": "¿Qué hacemos hoy?",
  "bond.torika.4": "Reconozco tus pasos.",
  "bond.torika.5": "Hay calma cuando estamos juntos.",
  "bond.torika.6": "Yo te cubro la espalda.",
  "bond.torika.7": "Te estaba esperando.",
  "bond.torika.8": "Me siento a salvo cuando vienes.",
  "bond.torika.9": "Iré contigo hasta el final.",
  "bond.torika.10": "Yo misma protegeré nuestro jardín.",
  "bond.rex.0": "No me toques.",
  "bond.rex.1": "¿No tienes miedo?",
  "bond.rex.2": "Un poco interesante.",
  "bond.rex.3": "Ven también a la próxima cacería.",
  "bond.rex.4": "Ya me sé tu olor.",
  "bond.rex.5": "No te apartes de mí.",
  "bond.rex.6": "Lo que venga a por ti, lo muerdo.",
  "bond.rex.7": "Hoy también llegas tarde.",
  "bond.rex.8": "Prefiero tu voz a las órdenes.",
  "bond.rex.9": "Eres mi única manada.",
  "bond.rex.10": "Estaré de tu lado para siempre.",
  "bond.spino.0": "…¿Qué pasa?",
  "bond.spino.1": "Echo de menos el agua.",
  "bond.spino.2": "Está bien quedarse en silencio.",
  "bond.spino.3": "Cuéntame más de ti.",
  "bond.spino.4": "Hoy las olas están tranquilas.",
  "bond.spino.5": "Me gusta pasear juntos.",
  "bond.spino.6": "Si hay peligro, ponte detrás de mí.",
  "bond.spino.7": "Sabía que vendrías.",
  "bond.spino.8": "Ya me he acostumbrado a esta ciudad.",
  "bond.spino.9": "Tu lado es mi agua.",
  "bond.spino.10": "Fluyamos juntos a donde sea.",
  "bond.generic.0": "Aún me resulta algo extraño.",
  "bond.generic.1": "Hoy nos vemos otra vez.",
  "bond.generic.2": "Me voy acostumbrando poco a poco.",
  "bond.generic.3": "Vamos juntos a una misión.",
  "bond.generic.4": "Me alegra que vengas.",
  "bond.generic.5": "Puedes quedarte a mi lado.",
  "bond.generic.6": "Esta vez también ayudaré.",
  "bond.generic.7": "Te estaba esperando.",
  "bond.generic.8": "Somos buenos compañeros.",
  "bond.generic.9": "Quiero que sigamos juntos mucho tiempo.",
  "bond.generic.10": "A partir de ahora cuento contigo.",
